document.getElementById("taskListBtn").addEventListener("click", () => refreshTasks().catch(err => alert(err.message)));
document.getElementById("adminTaskBtn").addEventListener("click", () => adminFetchTasks().catch(err => alert(err.message)));
document.getElementById("adminLogBtn").addEventListener("click", () => adminFetchLogs().catch(err => alert(err.message)));
