async function listRedeemCodes() {
  const used = document.getElementById("redeemUsed").value;
  const data = await api("/api/admin/redeem-code/list?used=" + encodeURIComponent(used), {
    headers: authHeaders(),
  });
  show("redeemPanel", data);
}

async function listTasks() {
  const userId = document.getElementById("taskUserId").value.trim();
  const status = document.getElementById("taskStatus").value.trim();
  const limit = Number(document.getElementById("taskLimit").value || 20);

  const q = new URLSearchParams();
  if (userId) q.set("user_id", userId);
  if (status) q.set("status", status);
  q.set("limit", String(limit));

  const data = await api("/api/admin/task/list?" + q.toString(), { headers: authHeaders() });
  show("taskPanel", data.filters);
  renderTasks(data.list || []);
}

async function retryTask() {
  const taskId = document.getElementById("retryTaskId").value.trim();
  if (!taskId) throw new Error("\u8BF7\u8F93\u5165 task_id");
  const data = await api("/api/admin/task/" + encodeURIComponent(taskId) + "/retry", {
    method: "POST",
    headers: authHeaders(),
    body: JSON.stringify({}),
  });
  show("taskPanel", data);
}

async function listCreditLogs() {
  const userId = document.getElementById("logUserId").value.trim();
  const taskId = document.getElementById("logTaskId").value.trim();
  const type = document.getElementById("logType").value.trim();

  const q = new URLSearchParams();
  if (userId) q.set("user_id", userId);
  if (taskId) q.set("task_id", taskId);
  if (type) q.set("type", type);

  const data = await api("/api/admin/credit-log/list?" + q.toString(), {
    headers: authHeaders(),
  });
  show("logPanel", data);
}

function bind(id, handler) {
  document.getElementById(id).addEventListener("click", () => {
    handler().catch((err) => alert(err.message || String(err)));
  });
}

setToken(state.token);
bind("saveTokenBtn", async () => setToken(document.getElementById("token").value));
bind("checkAdminBtn", checkAdmin);
bind("addCreditBtn", addCredits);
bind("createRedeemBtn", createRedeemCodes);
bind("listRedeemBtn", listRedeemCodes);
bind("listTaskBtn", listTasks);
bind("retryTaskBtn", retryTask);
bind("listLogBtn", listCreditLogs);
